def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    average = sum(values) / len(values)
    return {
        "value": average,
        "trace": {
            "values": values,
            "count": len(values),
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
